import numpy as np
one=np.ones_like(t)
Af={'1':one,'A':A,'A2':A**2,'A3':A**3,'1/A':1/A,'1/A2':1/A**2,'A/(1+A)':A/(1+A),'expA':np.exp(A),'expmA':np.exp(-A),'sqrtA':np.sqrt(A),'logA':np.log(A),'A4':A**4}
Tb=[one,t,t**2]
def sc(an):
    X=np.column_stack([Af[a]*b for a in an for b in Tb])
    c=np.linalg.lstsq(X,dA_dt,rcond=None)[0]
    r=dA_dt-X@c
    return np.mean(r**2)/np.var(dA_dt)
for an in [['1','A','A2','A3','1/A'],['1','A','A2','A3','1/A2'],['1','A','A2','A3','expA'],['1','A','A2','A3','expmA'],['1','A','A2','A3','A/(1+A)'],['1','A','A2','A3','logA'],['1','A','A2','A3','sqrtA'],['1','A','A2','A3','1/A','1/A2'],['1','A','A2','A3','A4']]:
    print(an, sc(an))
